    <script>
        // 处理论坛消息
        function processForumMessages() {
            const content = `$5`;
            const messages = content.match(/\[([^\]]+)\]([^[]+)/g);
            const container = document.getElementById('forumContent');

            if (messages && container) {
                container.innerHTML = '';
                messages.forEach(msg => {
                    const match = msg.match(/\[([^\]]+)\](.+)/);
                    if (match) {
                        const user = match[1];
                        const text = match[2].trim();
                        const postDiv = document.createElement('div');
                        postDiv.className = 'forum-post';
                        postDiv.innerHTML = `
                            <div class="post-avatar">${user.charAt(0)}</div>
                            <div class="post-content">
                                <div class="post-author">${user}</div>
                                <div class="post-time">刚刚</div>
                                <div class="post-text">（在论坛发出）${text}</div>
                                <div class="post-actions">
                                    <button class="post-action">👍 赞同</button>
                                    <button class="post-action">💬 回复</button>
                                    <button class="post-action">📤 分享</button>
                                </div>
                            </div>
                        `;
                        container.appendChild(postDiv);
                    }
                });
            }
        }

        function sendForumMessage() {
            const input = document.getElementById('forumInput');
            if (input.value.trim()) {
                const container = document.getElementById('forumContent');
                const postDiv = document.createElement('div');
                postDiv.className = 'forum-post';
                postDiv.innerHTML = `
                    <div class="post-avatar">我</div>
                    <div class="post-content">
                        <div class="post-author">我</div>
                        <div class="post-time">刚刚</div>
                        <div class="post-text">${input.value}</div>
                        <div class="post-actions">
                            <button class="post-action">👍 赞同</button>
                            <button class="post-action">💬 回复</button>
                            <button class="post-action">📤 分享</button>
                        </div>
                    </div>
                `;
                container.appendChild(postDiv);
                input.value = '';
                container.scrollTop = container.scrollHeight;
            }
        }

        function sendToChat() {
            const input = document.getElementById('forumInput');
            const message = input.value.trim();

            if (!message) {
                alert('请输入内容');
                return;
            }

            // 构建要发送的消息
            const formattedMessage = '（在论坛发出）' + message;

            // 尝试多种方式查找SillyTavern的输入框
            let stInput = document.querySelector('#send_textarea');
            if (!stInput) {
                stInput = parent.document.querySelector('#send_textarea');
            }
            if (!stInput) {
                stInput = top.document.querySelector('#send_textarea');
            }

            if (stInput) {
                // 设置输入框的值
                stInput.value = formattedMessage;
                stInput.dispatchEvent(new Event('input', { bubbles: true }));

                // 查找发送按钮
                let sendButton = document.querySelector('#send_but');
                if (!sendButton) {
                    sendButton = parent.document.querySelector('#send_but');
                }
                if (!sendButton) {
                    sendButton = top.document.querySelector('#send_but');
                }

                if (sendButton) {
                    sendButton.click();
                    input.value = '';
                    alert('消息已发送到聊天');
                } else {
                    alert('未找到发送按钮');
                }
            } else {
                alert('未找到聊天输入框');
            }
        }

        // 初始化
        processForumMessages();
    </script>
</body>
</html>
